SELECT m.chembl_id, m.pref_name, cs.canonical_smiles, ir.ref_id AS indication_curie, ir.ref_id AS indication_label, di.max_phase AS max_phase_for_ind FROM molecule_dictionary m LEFT JOIN compound_structures cs ON m.molregno = cs.molregno JOIN drug_indication di ON m.molregno = di.molregno JOIN indication_refs ir ON di.drugind_id = ir.drugind_id WHERE m.max_phase = 4 AND ir.ref_id = 'hypertension' ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles, ir.ref_id, ir.ref_id, di.max_phase
